=== purchase-unit
export type PurchaseUnit = {
  /**
   * The API caller-provided external ID for the purchase unit. Required for multiple purchase units
   * when you must update the order through `PATCH`. If you omit this value and the order contains
   * only one purchase unit, PayPal sets this value to `default`. Note: If there are multiple
   * purchase units, reference_id is required for each purchase unit.
   */
  referenceId?: string;
  /**
   * The total order amount with an optional breakdown that provides details, such as the total item
   * amount, total tax amount, shipping, handling, insurance, and discounts, if any. If you specify
   * `amount.breakdown`, the amount equals `item_total` plus `tax_total` plus `shipping` plus
   * `handling` plus `insurance` minus `shipping_discount` minus discount. The amount must be a
   * positive number. For listed of supported currencies and decimal precision, see the PayPal REST
   * APIs Currency Codes.
   */
  amount?: AmountWithBreakdown;
  /**
   * The merchant who receives the funds and fulfills the order. The merchant is also known as the
   * payee.
   */
  payee?: PayeeBase;
  /**
   * Any additional payment instructions to be consider during payment processing. This processing
   * instruction is applicable for Capturing an order or Authorizing an Order.
   */
  paymentInstruction?: PaymentInstruction;
  /** The purchase description. */
  description?: string;
  /**
   * The API caller-provided external ID. Used to reconcile API caller-initiated transactions with
   * PayPal transactions. Appears in transaction and settlement reports.
   */
  customId?: string;
  /** The API caller-provided external invoice ID for this order. */
  invoiceId?: string;
  /**
   * The PayPal-generated ID for the purchase unit. This ID appears in both the payer's transaction
   * history and the emails that the payer receives. In addition, this ID is available in
   * transaction and settlement reports that merchants and API callers can use to reconcile
   * transactions. This ID is only available when an order is saved by calling
   * v2/checkout/orders/id/save.
   */
  id?: string;
  /**
   * The payment descriptor on account transactions on the customer's credit card statement, that
   * PayPal sends to processors. The maximum length of the soft descriptor information that you can
   * pass in the API field is 22 characters, in the following format:22 - len(PAYPAL * (8)) -
   * len(Descriptor in Payment Receiving Preferences of Merchant account + 1)The PAYPAL prefix uses
   * 8 characters. The soft descriptor supports the following ASCII characters: Alphanumeric
   * characters Dashes Asterisks Periods (.) Spaces For Wallet payments marketplace integrations:
   * The merchant descriptor in the Payment Receiving Preferences must be the marketplace name. You
   * can't use the remaining space to show the customer service number. The remaining spaces can be
   * a combination of seller name and country. For unbranded payments (Direct Card) marketplace
   * integrations, use a combination of the seller name and phone number.
   */
  softDescriptor?: string;
  /** An array of items that the customer purchases from the merchant. */
  items?: Item[];
  /** The order shipping details. */
  shipping?: ShippingWithTrackingDetails;
  /**
   * Supplementary data about a payment. This object passes information that can be used to improve
   * risk assessments and processing costs, for example, by providing Level 2 and Level 3 payment
   * data.
   */
  supplementaryData?: SupplementaryData;
  /**
   * The collection of payments, or transactions, for a purchase unit in an order. For example,
   * authorized payments, captured payments, and refunds.
   */
  payments?: PaymentCollection;
  /**
   * The error reason code and description that are the reason for the most recent order decline.
   */
  mostRecentErrors?: Record<string, unknown>[];
};
=== payment-collection
export type PaymentCollection = {
  /**
   * An array of authorized payments for a purchase unit. A purchase unit can have zero or more
   * authorized payments.
   */
  authorizations?: AuthorizationWithAdditionalData[];
  /**
   * An array of captured payments for a purchase unit. A purchase unit can have zero or more
   * captured payments.
   */
  captures?: OrdersCapture[];
  /** An array of refunds for a purchase unit. A purchase unit can have zero or more refunds. */
  refunds?: Refund[];
};
=== captured-payment
export type CapturedPayment = {
  /** The status of the captured payment. */
  status?: CaptureStatus;
  /** The details of the captured payment status. */
  statusDetails?: CaptureStatusDetails;
  /** The PayPal-generated ID for the captured payment. */
  id?: string;
  /** The currency and amount for a financial transaction, such as a balance or payment due. */
  amount?: Money;
  /**
   * The API caller-provided external invoice number for this order. Appears in both the payer's
   * transaction history and the emails that the payer receives.
   */
  invoiceId?: string;
  /**
   * The API caller-provided external ID. Used to reconcile API caller-initiated transactions with
   * PayPal transactions. Appears in transaction and settlement reports.
   */
  customId?: string;
  /** Reference values used by the card network to identify a transaction. */
  networkTransactionReference?: NetworkTransaction;
  /**
   * The level of protection offered as defined by [PayPal Seller Protection for
   * Merchants](https://www.paypal.com/us/webapps/mpp/security/seller-protection).
   */
  sellerProtection?: SellerProtection;
  /**
   * Indicates whether you can make additional captures against the authorized payment. Set to
   * `true` if you do not intend to capture additional payments against the authorization. Set to
   * `false` if you intend to capture additional payments against the authorization.
   *
   * @default false
   */
  finalCapture?: boolean;
  /**
   * The detailed breakdown of the capture activity. This is not available for transactions that are
   * in pending state.
   */
  sellerReceivableBreakdown?: SellerReceivableBreakdown;
  /** The funds that are held on behalf of the merchant. @default DisbursementMode.Instant */
  disbursementMode?: DisbursementMode;
  /** An array of related [HATEOAS links](/docs/api/reference/api-responses/#hateoas-links). */
  links?: LinkDescription[];
  /**
   * The processor response information for payment requests, such as direct credit card
   * transactions.
   */
  processorResponse?: ProcessorResponse;
  /**
   * The date and time, in [Internet date and time
   * format](https://tools.ietf.org/html/rfc3339#section-5.6). Seconds are required while fractional
   * seconds are optional. Note: The regular expression provides guidance but does not reject all
   * invalid dates.
   */
  createTime?: string;
  /**
   * The date and time, in [Internet date and time
   * format](https://tools.ietf.org/html/rfc3339#section-5.6). Seconds are required while fractional
   * seconds are optional. Note: The regular expression provides guidance but does not reject all
   * invalid dates.
   */
  updateTime?: string;
  /** The supplementary data. */
  supplementaryData?: PaymentSupplementaryData;
  /**
   * The details for the merchant who receives the funds and fulfills the order. The merchant is
   * also known as the payee.
   */
  payee?: PayeeBase;
};
=== money
export type Money = {
  /**
   * The [three-character ISO-4217 currency
   * code](https://developer.paypal.com/api/rest/reference/currency-codes/) that identifies the
   * currency.
   */
  currencyCode: string;
  /**
   * The value, which might be: An integer for currencies like `JPY` that are not typically
   * fractional. A decimal fraction for currencies like `TND` that are subdivided into thousandths.
   * For the required number of decimal places for a currency code, see [Currency
   * Codes](https://developer.paypal.com/api/rest/reference/currency-codes/).
   */
  value: string;
};
=== link-description
export type LinkDescription = {
  /**
   * The complete target URL. To make the related call, combine the method with this [URI
   * Template-formatted](https://tools.ietf.org/html/rfc6570) link. For pre-processing, include the
   * `$`, `(`, and `)` characters. The `href` is the key HATEOAS component that links a completed
   * call with a subsequent call.
   */
  href: string;
  /**
   * The [link relation type](https://tools.ietf.org/html/rfc5988#section-4), which serves as an ID
   * for a link that unambiguously describes the semantics of the link. See [Link
   * Relations](https://www.iana.org/assignments/link-relations/link-relations.xhtml).
   */
  rel: string;
  /** The HTTP method required to make the related call. */
  method?: LinkHttpMethod;
};
=== order-application-context
export type OrderApplicationContext = {
  /**
   * DEPRECATED. The label that overrides the business name in the PayPal account on the PayPal
   * site. The fields in `application_context` are now available in the `experience_context` object
   * under the `payment_source` which supports them (eg.
   * `payment_source.paypal.experience_context.brand_name`). Please specify this field in the
   * `experience_context` object instead of the `application_context` object.
   *
   * @deprecated
   */
  brandName?: string;
  /**
   * DEPRECATED. The BCP 47-formatted locale of pages that the PayPal payment experience shows.
   * PayPal supports a five-character code. For example, `da-DK`, `he-IL`, `id-ID`, `ja-JP`,
   * `no-NO`, `pt-BR`, `ru-RU`, `sv-SE`, `th-TH`, `zh-CN`, `zh-HK`, or `zh-TW`. The fields in
   * `application_context` are now available in the `experience_context` object under the
   * `payment_source` which supports them (eg. `payment_source.paypal.experience_context.locale`).
   * Please specify this field in the `experience_context` object instead of the
   * `application_context` object.
   *
   * @deprecated
   */
  locale?: string;
  /**
   * DEPRECATED. DEPRECATED. The type of landing page to show on the PayPal site for customer
   * checkout. The fields in `application_context` are now available in the `experience_context`
   * object under the `payment_source` which supports them (eg.
   * `payment_source.paypal.experience_context.landing_page`). Please specify this field in the
   * `experience_context` object instead of the `application_context` object.
   *
   * @deprecated
   *
   * @default OrderApplicationContextLandingPage.NoPreference
   */
  landingPage?: OrderApplicationContextLandingPage;
  /**
   * DEPRECATED. DEPRECATED. The shipping preference: Displays the shipping address to the customer.
   * Enables the customer to choose an address on the PayPal site. Restricts the customer from
   * changing the address during the payment-approval process. . The fields in `application_context`
   * are now available in the `experience_context` object under the `payment_source` which supports
   * them (eg. `payment_source.paypal.experience_context.shipping_preference`). Please specify this
   * field in the `experience_context` object instead of the `application_context` object.
   *
   * @deprecated
   *
   * @default OrderApplicationContextShippingPreference.GetFromFile
   */
  shippingPreference?: OrderApplicationContextShippingPreference;
  /**
   * DEPRECATED. Configures a Continue or Pay Now checkout flow. The fields in `application_context`
   * are now available in the `experience_context` object under the `payment_source` which supports
   * them (eg. `payment_source.paypal.experience_context.user_action`). Please specify this field in
   * the `experience_context` object instead of the `application_context` object.
   *
   * @deprecated
   *
   * @default OrderApplicationContextUserAction.Continue
   */
  userAction?: OrderApplicationContextUserAction;
